/// <summary>
/// PaffH 11.10.25
/// </summary>
public class NDXBVEMailRequestLineItem extends common
{
}

Method.Source:
/// <summary>
/// PaffH 11.10.25
/// set itemid from barcode
/// </summary>
/// <returns>item found?</returns>
public boolean checkItemFromEanCode()
{
    boolean itemFound = false;
    InventTable inventTable = this.findInventTableByBarCode();
    itemFound = inventTable.RecId > 0;
    if (itemFound)
    {
        this.ItemId = inventTable.ItemId;
        this.ItemIdDataAreaId = inventTable.DataAreaId;
    }
    return itemFound;
}

/// <summary>
/// PaffH 11.10.25
/// last modified: PaffH 14.11.25
/// </summary>
public void update()
{
    if (this.ItemEANCode)
    {
        this.checkItemFromEanCode();
    }
    super();
}

/// <summary>
/// PaffH 11.10.25
/// last modified: PaffH 14.11.25
/// </summary>
public void insert()
{
    if (this.ItemEANCode)
    {
        this.checkItemFromEanCode();
    }
    super();
}

/// <summary>
/// PaffH 11.10.25
/// </summary>
/// <param name = "_barcodeSetupId">BarcodeSetupId default EAN13</param>
/// <returns>InventTable</returns>
public InventTable findInventTableByBarCode(BarcodeSetupId _barcodeSetupId = 'EAN13')
{
    InventItemBarcode inventItemBarcode;
    InventTable inventTable;

    select firstonly crosscompany inventItemBarcode
        where inventItemBarcode.barcodeSetupId == _barcodeSetupId
        && inventItemBarcode.itemBarCode == this.ItemEANCode;
    if (inventItemBarcode)
    {
        changecompany(inventItemBarcode.DataAreaId)
        {
            inventTable = InventTable::find(inventItemBarcode.itemId);
        }
    }

    return inventTable;
}

/// <summary>
/// PaffH 18.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestLine">NDXBVEMailRequestLine</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXBVEMailRequestLineItem</returns>
public static NDXBVEMailRequestLineItem findFromNDXBVEMailRequestLine(NDXBVEMailRequestLine _nDXBVEMailRequestLine, boolean _forUpdate = false)
{
    NDXBVEMailRequestLineItem nDXBVEMailRequestLineItem;
    nDXBVEMailRequestLineItem.selectForUpdate(_forUpdate);
    select firstonly nDXBVEMailRequestLineItem
        where nDXBVEMailRequestLineItem.IdentifierGUID == _nDXBVEMailRequestLine.IdentifierGUID
        && nDXBVEMailRequestLineItem.IdentifierLine == _nDXBVEMailRequestLine.IdentifierLine
        && nDXBVEMailRequestLineItem.ItemId == _nDXBVEMailRequestLine.ItemId
        && nDXBVEMailRequestLineItem.ItemIdDataAreaId == _nDXBVEMailRequestLine.ItemIdDataAreaId;
    return nDXBVEMailRequestLineItem;
}

/// <summary>
/// PaffH 21.10.25
/// </summary>
/// <param name = "_recId">RecId</param>
/// <returns>rec exists</returns>
public static boolean exists(RecId _recId)
{
    return _recId > 0 &&
        (select firstonly RecId from NDXBVEMailRequestLine where NDXBVEMailRequestLine.RecId == _recId).RecId > 0;
}

/// <summary>
/// PaffH 03.11.25
/// last modified: PaffH 12.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestLine">NDXBVEMailRequestLine</param>
/// <returns>NDXBVEMailRequestLine</returns>
public static NDXBVEMailRequestLineItem insertFromNDXBVEMailRequestLine(NDXBVEMailRequestLine _nDXBVEMailRequestLine)
{
    NDXBVEMailRequestLineItem nDXBVEMailRequestLineItem;
    nDXBVEMailRequestLineItem.initValue();
    nDXBVEMailRequestLineItem.initFromNDXBVEMailRequestLine(_nDXBVEMailRequestLine);
    nDXBVEMailRequestLineItem.IdentifierLine2 = nDXBVEMailRequestLineItem.nextIdentifierLine2();
    nDXBVEMailRequestLineItem.Manual = NoYes::Yes;
    //nDXBVEMailRequestLineItem.SelectItem = NoYes::Yes;
    nDXBVEMailRequestLineItem.insert();
    NDXBVEMailRequestLineItem::checkItemSelect(nDXBVEMailRequestLineItem);
    return nDXBVEMailRequestLineItem;
}

/// <summary>
/// PaffH 03.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestLine">NDXBVEMailRequestLine</param>
public void initFromNDXBVEMailRequestLine(NDXBVEMailRequestLine _nDXBVEMailRequestLine)
{
    this.IdentifierGUID = _nDXBVEMailRequestLine.IdentifierGUID;
    this.IdentifierLine = _nDXBVEMailRequestLine.IdentifierLine;
}

/// <summary>
/// PaffH 03.11.25
/// </summary>
/// <returns>next IdentiferLine2</returns>
protected Line nextIdentifierLine2()
{
    NDXBVEMailRequestLineItem nDXBVEMailRequestLineItem;
    select firstonly nDXBVEMailRequestLineItem 
        order by IdentifierLine2 desc
        where nDXBVEMailRequestLineItem.IdentifierGUID == this.IdentifierGUID
        && nDXBVEMailRequestLineItem.IdentifierLine == this.IdentifierLine;
    return nDXBVEMailRequestLineItem.IdentifierLine2 + 1;
}

/// <summary>
/// PaffH 03.11.25
/// delete manual record
/// </summary>
/// <returns>deleted ?</returns>
public boolean deleteManual()
{
    if (this.Manual == NoYes::Yes)
    {
        if (this.validateDelete())
        {
            ttsbegin;
            this.delete();
            ttscommit;
            return true;
        }
    }
    return false;
}

/// <summary>
/// PaffH 03.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestLineItem">NDXBVEMailRequestLineItem</param>
/// <returns>boolean</returns>
public static boolean checkItemSelect(NDXBVEMailRequestLineItem _nDXBVEMailRequestLineItem)
{
    NDXBVEMailRequestLineItem nDXBVEMailRequestLineItem;
    FormDataSource fds;
    if (FormDataUtil::isFormDataSource(_nDXBVEMailRequestLineItem))
    {
        fds = FormDataUtil::getFormDataSource(_nDXBVEMailRequestLineItem);
    }
    Query q = new Query();
    QueryBuildDataSource qbds = q.addDataSource(tableNum(NDXBVEMailRequestLineItem));
    qbds.update(true);
    qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierGUID)).value(queryValue(_nDXBVEMailRequestLineItem.IdentifierGUID));
    qbds.addRange(fieldNum(NDXBVEMailRequestLineItem, IdentifierLine)).value(queryValue(_nDXBVEMailRequestLineItem.IdentifierLine));
    QueryRun qr = new QueryRun(q);
    ttsbegin;
    boolean changed = false;
    while (qr.next())
    {
        nDXBVEMailRequestLineItem = qr.get(tableNum(NDXBVEMailRequestLineItem));
        if (nDXBVEMailRequestLineItem.SelectItem == NoYes::Yes && nDXBVEMailRequestLineItem.RecId != _nDXBVEMailRequestLineItem.RecId)
        {
            nDXBVEMailRequestLineItem.SelectItem = NoYes::No;
            nDXBVEMailRequestLineItem.update();
            changed = true;
        }
    }
    ttscommit;

    //if (changed && fds)
    //{
    //    //fds.research(true);
    //}
    return changed;
}

/// <summary>
/// PaffH 14.11.25
/// </summary>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXBVEMailRequestHeader</returns>
public NDXBVEMailRequestHeader nDXBVEMailRequestHeader(boolean _forUpdate = false)
{
    return NDXBVEMailRequestHeader::findFromGUID(this.IdentifierGUID, _forUpdate);
}
